            return hipModuleLaunchKernel(_pa_decode_reduce_kernel256_16_32_func, gX, gY, gZ, 4 * warpSize, 1, 1, 2048, stream, args, nullptr);
            else
            return hipErrorInvalidValue;
        }
        #undef HIP_CHECK
